(function(){
 'use strict';
 const C=VeredaTeam,$=id=>document.getElementById(id),people=[{id:'camila',name:'Camila · exemplo'},{id:'rafael',name:'Rafael · exemplo'},{id:'luiza',name:'Luiza · exemplo'}];
 const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=offset=>new Date(C.day(selectedWeek)+offset*86400000).toISOString().slice(0,10);
 const format=d=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(new Date(C.day(d)));
 const clock=()=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(new Date());
 const person=id=>people.find(p=>p.id===id)?.name||'Pessoa indisponível';
 const money=cents=>(cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 let shifts=[],requests=[],reads={},onboarding={},events=[],counter=20,selectedWeek='2026-10-26';
 function audit(text){events.unshift(clock()+' — '+text);$('audit').innerHTML=events.map(x=>'<li>'+esc(x)+'</li>').join('');}
 function status(id,text,error=false){$(id).textContent=text;$(id).classList.toggle('error',error);}
 function seed(){shifts=[{id:'s1',person:'camila',date:'2026-10-26',start:'09:00',end:'17:00',pause:60,commission:25,role:'Recepção',nextDay:false},{id:'s2',person:'rafael',date:'2026-10-26',start:'12:00',end:'20:00',pause:60,commission:0,role:'Atendimento',nextDay:false},{id:'s3',person:'luiza',date:'2026-10-27',start:'08:00',end:'16:00',pause:60,commission:40,role:'Operação',nextDay:false},{id:'s4',person:'rafael',date:'2026-10-30',start:'22:00',end:'06:00',pause:60,commission:0,role:'Operação',nextDay:true}];requests=[{id:'r1',kind:'swap',shift:'s3',person:'luiza',target:'camila',status:'pending'},{id:'r2',kind:'leave',person:'rafael',from:'2026-11-02',to:'2026-11-02',status:'pending'}];reads={};onboarding={};events=[];counter=20;selectedWeek='2026-10-26';$('week-start').value=selectedWeek;$('person-filter').value='all';$('shift-form').reset();$('request-form').reset();$('reader').value=people[0].id;updateRequestFields();audit('Exemplos restaurados. Nenhum registro de trabalho real.');render();}
 for(const id of ['shift-person','request-person','request-target','reader'])$(id).innerHTML=people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');
 $('person-filter').insertAdjacentHTML('beforeend',people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join(''));
 function render(){
  const start=selectedWeek,end=date(6),selected=$('person-filter').value;
  const days=['SEG','TER','QUA','QUI','SEX','SÁB','DOM'];
  $('week').innerHTML=days.map((name,i)=>{const d=date(i),list=C.dayShifts(shifts,d,selected);return `<section class="day-column"><h3>${name}<b>${d.slice(8)}</b></h3>${list.map(s=>`<article class="shift"><strong>${esc(person(s.person))}</strong><small>${s.date===d?s.start+'–'+s.end+(s.nextDay?' +1 dia':''):'00:00–'+s.end+' · continuação'}</small>${s.date!==d?'<small>Início em '+format(s.date)+' às '+s.start+'</small>':''}${esc(s.role)}<small>Intervalo do turno: ${s.pause} min</small><button type="button" data-remove="${s.id}" aria-label="Remover turno de ${esc(person(s.person))} iniciado em ${format(s.date)} às ${s.start}">Remover</button></article>`).join('')||'<p class="empty">Sem turno</p>'}</section>`}).join('');
  $('shift-count').textContent=shifts.filter(s=>s.date>=start&&s.date<=end).length+' turnos iniciados na semana';
  $('request-shift').innerHTML=shifts.map(s=>`<option value="${s.id}">${esc(person(s.person))} · ${format(s.date)} · ${s.start}–${s.end}</option>`).join('');
  $('requests').innerHTML=requests.map(r=>{const s=shifts.find(s=>s.id===r.shift),title=r.kind==='swap'?'Troca de responsável':r.kind==='vacation'?'Pedido de férias':'Pedido de folga',desc=r.kind==='swap'?(s?`${person(r.person)} → ${person(r.target)} · ${format(s.date)} · ${s.start}–${s.end}`:(r.status==='pending'?'Turno removido. Solicitação precisa ser recusada.':'Turno posteriormente removido da escala.')):`${person(r.person)} · ${format(r.from)} a ${format(r.to)}`;return `<article class="request-item" id="request-${r.id}" tabindex="-1" aria-labelledby="request-title-${r.id}"><span class="tag">${r.status==='pending'?'Aguardando revisão':r.status==='approved'?'Aprovação simulada':'Recusada na simulação'}</span><h3 id="request-title-${r.id}">${title}</h3><p>${esc(desc)}</p>${r.status==='pending'?`<div class="actions"><button class="button secondary" type="button" data-approve="${r.id}">Simular aprovação</button><button class="button quiet" type="button" data-reject="${r.id}">Recusar</button></div>`:''}</article>`}).join('')||'<p>Sem solicitações nesta sessão.</p>';
  const rows=C.summary(shifts,people,start,end);$('report-period').textContent=format(start)+' a '+format(end);
  $('summary').innerHTML=rows.map(r=>`<tr><td>${esc(r.person)}</td><td>${r.shifts}</td><td>${Math.floor(r.minutes/60)}h ${r.minutes%60}min</td><td>${money(r.commissionCents)}</td></tr>`).join('');
  renderBoard();renderOnboarding();
 }
 function renderBoard(){const notices=[['abertura','Abertura da operação','Confira materiais e canais de atendimento antes do primeiro horário. Pendências devem ser comunicadas ao responsável.'],['privacidade','Informação certa, no lugar certo','Documentos de clientes e colaboradores devem circular somente nos canais autorizados. Não use esta demonstração para dados pessoais.']];$('notice-board').innerHTML=notices.map(([id,title,text])=>{const read=reads[id]||{},name=$('reader').value;return `<article class="notice-card"><h3>${title}</h3><p>${text}</p><button class="button secondary" type="button" data-read="${id}" ${read[name]?'disabled':''}>${read[name]?'Leitura simulada registrada':'Simular minha confirmação de leitura'}</button><div class="read-list">${Object.entries(read).map(([p,t])=>`Lido e confirmado por ${esc(person(p))} em ${esc(t)} · simulação`).join('<br>')||'Nenhuma confirmação simulada.'}</div></article>`}).join('');}
 function renderOnboarding(){const items=['Orientações iniciais conferidas','Treinamento de rotina concluído','Canal de apoio apresentado'];$('onboarding').innerHTML=people.map(p=>`<article class="person-card"><h3>${esc(p.name)}</h3>${items.map((text,i)=>`<label class="check"><input type="checkbox" data-onboard="${p.id}:${i}" ${onboarding[p.id+':'+i]?'checked':''}><span>${text}</span></label>`).join('')}<p class="hint">Checklist simulado. Sem documentos anexados.</p></article>`).join('');}
 $('week-start').addEventListener('change',()=>{try{const range=C.weekRange($('week-start').value);selectedWeek=range.from;$('week-start').value=selectedWeek;render();status('schedule-status','Semana atualizada.');}catch(e){$('week-start').value=selectedWeek;status('schedule-status',e.message+' A última semana válida foi mantida.',true);}});
 $('person-filter').addEventListener('change',render);$('reader').addEventListener('change',renderBoard);
 $('shift-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;try{const f=new FormData(e.target),s={id:'s'+(++counter),person:f.get('person'),date:f.get('date'),start:f.get('start'),end:f.get('end'),pause:Number(f.get('pause')),commission:Number(f.get('commission')),role:f.get('role'),nextDay:f.has('nextDay')};C.validateShift(s,shifts,requests,people);shifts.push(s);audit('Turno planejado para '+person(s.person)+' em '+format(s.date)+'.');render();status('shift-status','Turno adicionado. Se estiver fora da semana exibida, altere a referência.');}catch(err){status('shift-status',err.message,true);}});
 $('week').addEventListener('click',e=>{const id=e.target.closest('[data-remove]')?.dataset.remove;if(!id)return;shifts=shifts.filter(s=>s.id!==id);audit('Turno removido da escala demonstrativa.');render();status('schedule-status','Turno removido. As solicitações vinculadas continuam para revisão.');});
 function updateRequestFields(){const swap=$('request-kind').value==='swap';$('leave-fields').hidden=swap;$('swap-fields').hidden=!swap;for(const i of $('leave-fields').querySelectorAll('input,select'))i.disabled=swap;for(const i of $('swap-fields').querySelectorAll('select'))i.disabled=!swap;}
 $('request-kind').addEventListener('change',updateRequestFields);
 $('request-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;try{const f=new FormData(e.target),r={id:'r'+(++counter),kind:f.get('kind'),status:'pending'};if(r.kind==='swap'){const s=shifts.find(s=>s.id===f.get('shift'));if(!s)throw Error('Adicione um turno antes de solicitar uma troca.');if(s.person===f.get('target'))throw Error('Escolha outra pessoa para assumir o turno.');r.shift=s.id;r.person=s.person;r.target=f.get('target');}else{r.person=f.get('person');r.from=f.get('from');r.to=f.get('to');if(C.day(r.to)<C.day(r.from))throw Error('Confira o início e o fim da ausência.');}requests.push(r);audit('Nova solicitação de '+person(r.person)+' preparada.');render();status('request-status','Solicitação aguardando revisão. Nenhuma escala foi alterada.');}catch(err){status('request-status',err.message,true);}});
 $('requests').addEventListener('click',e=>{const approve=e.target.closest('[data-approve]')?.dataset.approve,reject=e.target.closest('[data-reject]')?.dataset.reject,id=approve||reject,r=requests.find(x=>x.id===id);if(!r||r.status!=='pending')return;try{if(approve){if(r.kind==='swap'){const s=shifts.find(s=>s.id===r.shift);if(!s||s.person!==r.person)throw Error('O turno mudou desde a solicitação. Recuse e prepare uma nova troca.');const next={...s,person:r.target};C.validateShift(next,shifts,requests,people);Object.assign(s,next);}else C.validateLeave(r,shifts,requests,people);r.status='approved';}else r.status='rejected';audit('Solicitação '+r.id+' '+(approve?'aprovada':'recusada')+' na simulação.');render();$('request-'+r.id)?.focus({preventScroll:true});status('request-status','Decisão demonstrativa registrada.');}catch(err){status('request-status',err.message,true);}});
 $('notice-board').addEventListener('click',e=>{const id=e.target.closest('[data-read]')?.dataset.read;if(!id)return;const who=$('reader').value;reads[id]??={};if(reads[id][who])return;reads[id][who]=clock();audit('Leitura do comunicado simulada por '+person(who)+'.');renderBoard();});
 $('onboarding').addEventListener('change',e=>{const id=e.target.dataset.onboard;if(!id)return;onboarding[id]=e.target.checked;audit('Checklist de integração atualizado na simulação.');});
 $('export-csv').addEventListener('click',()=>{const start=selectedWeek,end=date(6);const blob=new Blob([C.csv(C.summary(shifts,people,start,end),start,end)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='vereda-pre-folha-informativa-'+start+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);audit('Resumo de exemplo exportado em CSV.');});
 $('print-report').addEventListener('click',()=>window.print());$('reset-team').addEventListener('click',()=>{seed();for(const id of ['shift-status','request-status','schedule-status'])status(id,'');});
 function updateSectionNavigation(){const links=[...document.querySelectorAll('.op-tabs a')],active=links.some(a=>a.getAttribute('href')===location.hash)?location.hash:'#escala';links.forEach(a=>{if(a.getAttribute('href')===active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}
 window.addEventListener('hashchange',updateSectionNavigation);updateSectionNavigation();seed();
})();
